messages.content:
Write a single self-contained HTML file with a 3D animation using three.js. three.js r160 is available as an ES module at './three.module.js' -- import it with:
  import * as THREE from './three.module.js';
Scene: two cars race on a straight track toward a visible finish line. One car is bright RED, the other bright BLUE. The blue car leads early, then the red car accelerates, overtakes mid-race, and wins. After the red car crosses the finish line the race resets and loops forever. Both cars must be clearly visible and large enough to follow throughout (fill a meaningful part of the frame). Simple ground and sky, camera keeps both cars in view. No external assets besides the three.js import. Output ONLY the HTML in one code block.

response.text:
Here is the complete, self-contained HTML file. You can save this as an `.html` file (e.g., `race.html`) and open it in any modern browser.

```html
<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Three.js Car Race</title>
    <style>
        body { margin: 0; overflow: hidden; background-color: #87CEEB; }
        canvas { display: block; }
    </style>
</head>
<body>
    <!-- Import Map for Three.js r160 -->
    <script type="importmap">
        {
            "imports": {
                "three": "./three.module.js"
            }
        }
    </script>

    <script type="module">
        import * as THREE from './three.module.js';

        // --- Configuration ---
        const TRACK_LENGTH = 1000;
        const FINISH_LINE = 900;
        const LANE_OFFSET = 6;

        // Animation State
        let animationId;
        let resetTriggered = false;
        let raceFinished = false;

        // --- Scene Setup ---
        const scene = new THREE.Scene();
        scene.background = new THREE.Color(0x87CEEB); // Sky Blue
        scene.fog = new THREE.Fog(0x87CEEB, 20, 150); // Fog to fade distant objects

        const camera = new THREE.PerspectiveCamera(60, window.innerWidth / window.innerHeight, 0.1, 1000);

        const renderer = new THREE.WebGLRenderer({ antialias: true });
        renderer.setSize(window.innerWidth, window.innerHeight);
        renderer.shadowMap.enabled = true;
        document.body.appendChild(renderer.domElement);

        // --- Lighting ---
        const ambientLight = new THREE.AmbientLight(0xffffff, 0.6);
        scene.add(ambientLight);

        const dirLight = new THREE.DirectionalLight(0xffffff, 1);
        dirLight.position.set(10, 50, 20);
        dirLight.castShadow = true;
        dirLight.shadow.camera.left = -50;
        dirLight.shadow.camera.right = 50;
        dirLight.shadow.camera.top = 50;
        dirLight.shadow.camera.bottom = -50;
        dirLight.shadow.mapSize.width = 2048;
        dirLight.shadow.mapSize.height = 2048;
        scene.add(dirLight);

        // --- Environment (Ground & Track) ---

        // Grass Ground
        const planeGeometry = new THREE.PlaneGeometry(1000, 2000);
        const planeMaterial = new THREE.MeshStandardMaterial({ color: 0x228B22 });
        const ground = new THREE.Mesh(planeGeometry, planeMaterial);
        ground.rotation.x = -Math.PI / 2;
        ground.position.y = -0.1;
        ground.position.z = 500;
        ground.receiveShadow = true;
        scene.add(ground);

        // Asphalt Track
        const trackGeometry = new THREE.PlaneGeometry(20, 1200);
        const trackMaterial = new THREE.MeshStandardMaterial({ color: 0x333333 });
        const track = new THREE.Mesh(trackGeometry, trackMaterial);
        track.rotation.x = -Math.PI / 2;
        track.position.y = 0;
        track.position.z = 500;
        track.receiveShadow = true;
        scene.add(track);

        // Finish Line (Checkerboard Pattern via Canvas Texture)
        const canvas = document.createElement('canvas');
        canvas.width = 128;
        canvas.height = 128;
        const ctx = canvas.getContext('2d');
        ctx.fillStyle = '#FFFFFF';
        ctx.fillRect(0, 0, 128, 128);
        ctx.fillStyle = '#000000';
        for(let i=0; i<4; i++) {
            for(let j=0; j<4; j++) {
                if ((i+j)%2 === 0) ctx.fillRect(i*32, j*32, 32, 32);
            }
        }
        const texture = new THREE.CanvasTexture(canvas);
        texture.wrapS = THREE.RepeatWrapping;
        texture.wrapT = THREE.RepeatWrapping;
        texture.repeat.set(10, 1);

        const finishGeometry = new THREE.PlaneGeometry(18, 10);
        const finishMaterial = new THREE.MeshBasicMaterial({ map: texture });
        const finishLine = new THREE.Mesh(finishGeometry, finishMaterial);
        finishLine.rotation.x = -Math.PI / 2;
        finishLine.position.set(0, 0.1, FINISH_LINE);
        scene.add(finishLine);

        // --- Car Creation ---
        function createCar(color) {
            const carGroup = new THREE.Group();

            // Chassis
            const chassisGeo = new THREE.BoxGeometry(2.5, 1, 5);
            const chassisMat = new THREE.MeshStandardMaterial({ color: color, roughness: 0.2, metalness: 0.1 });
            const chassis = new THREE.Mesh(chassisGeo, chassisMat);
            chassis.position.y = 1;
            chassis.castShadow = true;
            carGroup.add(chassis);

            // Cabin
            const cabinGeo = new THREE.BoxGeometry(2, 0.8, 2.5);
            const cabinMat = new THREE.MeshStandardMaterial({ color: 0x333333, roughness: 0.1 }); // Dark glass
            const cabin = new THREE.Mesh(cabinGeo, cabinMat);
            cabin.position.set(0, 1.8, -0.5);
            cabin.castShadow = true;
            carGroup.add(cabin);

            // Wheels
            const wheelGeo = new THREE.CylinderGeometry(0.6, 0.6, 0.4, 16);
            const wheelMat = new THREE.MeshStandardMaterial({ color: 0x111111 });

            const positions = [
                { x: -1.2, z: 1.5 }, { x: 1.2, z: 1.5 },
                { x: -1.2, z: -1.5 }, { x: 1.2, z: -1.5 }
            ];

            positions.forEach(pos => {
                const wheel = new THREE.Mesh(wheelGeo, wheelMat);
                wheel.rotation.z = Math.PI / 2;
                wheel.position.set(pos.x, 0.6, pos.z);
                wheel.castShadow = true;
                carGroup.add(wheel);
            });

            return carGroup;
        }

        const redCar = createCar(0xff0000);
        const blueCar = createCar(0x0000ff);

        scene.add(redCar);
        scene.add(blueCar);

        // --- Animation Logic ---

        // Reset function
        function resetRace() {
            redCar.position.z = 0;
            blueCar.position.z = 0;
            raceFinished = false;
            resetTriggered = false;
        }

        // Speed parameters
        let redSpeed = 1.2;
        let blueSpeed = 1.0;
        let redAccel = 0.002; // Acceleration factor
        let blueAccel = 0.0005;

        function animate() {
            animationId = requestAnimationFrame(animate);

            if (!raceFinished) {
                // Move cars
                // Red car starts slower but accelerates more aggressively
                redSpeed += redAccel;
                blueSpeed += blueAccel;

                // Cap speeds
                if (redSpeed > 2.5) redSpeed = 2.5;
                if (blueSpeed > 1.8) blueSpeed = 1.8;

                redCar.position.z += redSpeed;
                blueCar.position.z += blueSpeed;

                // Check win condition
                if (redCar.position.z > FINISH_LINE) {
                    raceFinished = true;
                    resetTriggered = true;
                }
            } else {
                // Reset Logic
                if (resetTriggered) {
                    // Wait a moment then reset positions smoothly
                    if (redCar.position.z > FINISH_LINE + 10) {
                        resetRace();
                    }
                }
            }

            // Camera Follow Logic
            // Target position is slightly behind the leader
            const leaderZ = Math.max(redCar.position.z, blueCar.position.z);
            const targetCamZ = leaderZ - 40;
            const targetCamY = 15;

            // Smooth camera movement
            camera.position.z += (targetCamZ - camera.position.z) * 0.05;
            camera.position.y += (targetCamY - camera.position.y) * 0.05;

            // Look at point between cars
            const midZ = (redCar.position.z + blueCar.position.z) / 2;
            camera.lookAt(0, 2, midZ + 20);

            renderer.render(scene, camera);
        }

        // Initial Camera Position
        camera.position.set(0, 15, -20);
        camera.lookAt(0, 2, 0);

        // Handle Window Resize
        window.addEventListener('resize', () => {
            camera.aspect = window.innerWidth / window.innerHeight;
            camera.updateProjectionMatrix();
            renderer.setSize(window.innerWidth, window.innerHeight);
        });

        // Start
        animate();

    </script>
</body>
</html>
```
